module GitPullRequests
  # On a pull request's page, the Source branch and Target branch values link
  # to the branch in Redmine's repository browser. A branch that doesn't
  # exist is shown in red while the pull request is open (after the merge,
  # a deleted branch is normal), without a link.
  # Prepended to Redmine::FieldFormat::StringFormat.
  module BranchLinks
    def formatted_custom_value(view, custom_value, html = false)
      (html && GitPullRequests::BranchLinks.link(view, custom_value)) || super
    end

    # The link or red name, or nil for Redmine's own formatting
    def self.link(view, custom_value)
      # Only on the issue page: not in lists (a git call per row) or mails
      return unless view.respond_to?(:controller_name) &&
                    view.controller_name == 'issues' && view.action_name == 'show'

      issue = custom_value.customized
      return unless issue.is_a?(Issue) && PullRequest.pull_request?(issue)
      return unless [PullRequest::SOURCE_FIELD, PullRequest::TARGET_FIELD].include?(custom_value.custom_field.name)

      pr = PullRequest.new(issue)
      name = custom_value.value.to_s.strip
      return unless pr.repository && PullRequest::BRANCH_NAME.match?(name)
      return unless User.current.allowed_to?(:browse_repository, pr.repository.project)

      if pr.branch_exists?(name)
        view.link_to(name, controller: 'repositories', action: 'show', id: pr.repository.project,
                           repository_id: pr.repository.identifier_param, rev: name)
      elsif !issue.closed?
        view.tag.span(name, style: 'color: #c00', title: "Branch #{name} doesn't exist")
      end
    rescue StandardError => e
      # A broken plugin mustn't break the issue page: Redmine's plain value then
      Rails.logger.error("git_pull_requests: ##{issue&.id}: #{e.class}: #{e.message}")
      nil
    end
  end
end
